def minCostToOne(n, a, b, c):
    f = [0] * (n + 1)
    for m in range(2, n + 1):
        best = f[m - 1] + a
        if m % 2 == 0 and f[m // 2] + b < best:
            best = f[m // 2] + b
        if m % 3 == 0 and f[m // 3] + c < best:
            best = f[m // 3] + c
        f[m] = best
    return f[n]
